@Bean
RabbitTemplate template(ConnectionFactory cf) {
    RabbitTemplate t = new RabbitTemplate(cf);
    t.setReplyTimeout(5_000);           // direct reply-to is the default
    return t;
}

// caller: address and correlation are filled in by the template
Object answer = template.convertSendAndReceive("", "rpc_queue", "10");

